from pathlib import Path
import subprocess,sys,os,json,hashlib
W=Path(__file__).resolve().parents[1];v=sys.argv[1];f=W/'proofs'/('scripted-new-sequence.mp4' if v=='scripted' else 'off-the-cuff-definition-comparison.mp4');d=W/'proofs'/('review-'+v);d.mkdir(exist_ok=True)
assert f.exists() and not (d/'answer.txt').exists()
q='''Review this actual bounded engineering context with its actual sound, completely. It is part of a dedicated organic Dad Bod reaction Short, not a full-film review. Report observed facts and actual audible words. The requested sequence is: native street interview crop, then whole 16:9 horizontal panel still speaking, then source sound stops and real Dan responds with that interview moving SILENTLY behind his FOREGROUND HAIR, followed by a full-screen real-photo comparison: Seth Rogen red X, Daniel Craig green check; then presenter on moving blue field. Scripted context starts at film8 seconds; off-cuff context starts at film18 seconds, so it does not include the opening transition. Title/source above the horizontal panel. Note: this engineering scripted proof has an earlier shorter source title; exact full title is already built for final. Do not call that a defect in the future full film. The chosen sound is Balanced and chosen grade Warm & Vivid, preserve their character. Judge transition coherence, clipping/doubled speech, source still audible under Dan, silent moving panel vs freeze, whole-height source, foreground hair layer ordering, source faces/insets, caption identity/sync/clearance, readability of real X/check comparison, graphic motion and whether the actual choice illustrates the definition line. List only observed defects with LOCAL timestamps, exact words and fix. If uncertain, say uncertain. Include actual first and last words, a literal transcript, and PASS/FAIL per picture, sound, captions. Never infer full-film QA or Dan approval from this excerpt. No general legal commentary.'''
(d/'prompt.txt').write_text(q);(d/'provenance.json').write_text(json.dumps({'file':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'version':v,'film_offset':8 if v=='scripted' else 18},indent=2))
r=subprocess.run([sys.executable,str(W/'recipe/quality_listen_r2.py'),str(d/'prompt.txt'),str(f)],capture_output=True,text=True,env=dict(os.environ,GM='gemini-3.1-pro-preview'))
(d/'answer.txt').write_text(r.stdout+r.stderr)
b=W/'quality-review-budget.json';rec=json.loads(b.read_text());rec['provider_call_count']+=1;rec['provider_usage'].append(dict(scope='engineering context '+v,returncode=r.returncode,usage=r.stdout.split('USAGE')[-1].strip() if 'USAGE' in r.stdout else None,answer=str(d/'answer.txt')));b.write_text(json.dumps(rec,indent=2));print('BOUNDED_AV_REVIEW',v,r.returncode,flush=True)
if r.returncode:raise SystemExit('Provider refused/failed; do not retry same call.')
